use std::collections::HashSet;

/// Removes duplicates from the input vector `nums`.
/// Returns a new vector containing the unique elements from `nums`.
/// 
/// Postconditions:
///  1. The result contains no duplicates.
///  2. The set of elements in the result equals the set of elements in the input.
/// 
/// This is achieved by iterating over the input and inserting into a HashSet 
/// to track seen items. The order of first occurrence is preserved.
fn remove_duplicates(nums: Vec<i32>) -> Vec<i32> {
    let mut seen = HashSet::new();
    let mut result = Vec::new();

    for num in nums {
        if seen.insert(num) {
            // insert returns true only if the element was not already present
            result.push(num);
        }
    }

    result
}

